<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PersonalLedgerNav from '../components/PersonalLedgerNav.vue'
import { useWorkspaceStore } from '../stores/workspace'
import { useAuthStore } from '../stores/auth'
import { useI18n } from '../i18n'
import type { Currency } from '../api/types'

const route = useRoute()
const router = useRouter()
const workspace = useWorkspaceStore()
const auth = useAuthStore()
const { tr, locale } = useI18n()
const open = ref(false)
const datePicker = ref<HTMLInputElement>()
const mode = ref<'expense'|'income'|'subscription'>('expense')
const saving = ref(false)
const loadError = ref('')
const form = reactive({ title: '', amount: '', currency: (auth.record?.defaultCurrency || 'TWD') as Currency, category: '', date: '', notes: '', billingCycle: 'monthly' })
const today = () => new Date().toISOString().slice(0, 10)
const date = computed(() => String(route.query.date || workspace.personalLedger?.date || today()))
const ledger = computed(() => workspace.personalLedger)
const items = computed(() => ledger.value?.items || [])
function sourceLabel(item: { groupId?: string }) { return item.groupId ? workspace.groups.find(group => group.id === item.groupId)?.name || item.groupId : tr('privateRecord') }
const label = computed(() => {
  const value = new Date(date.value + 'T12:00:00')
  return Number.isNaN(value.getTime()) ? date.value : new Intl.DateTimeFormat(locale.value, { month: 'long', day: 'numeric', weekday: 'short' }).format(value)
})
const money = (value: number, currency: Currency) => new Intl.NumberFormat(locale.value, { style: 'currency', currency, maximumFractionDigits: 2 }).format(value / 100)
function statusLabel(status: string) { return tr(status === 'scheduled' ? 'scheduled' : status === 'failed' ? 'failed' : status === 'pending' ? 'pendingLedger' : 'recorded') }
function move(days: number) { const value = new Date(date.value + 'T12:00:00'); value.setDate(value.getDate() + days); router.replace({ query: { ...route.query, date: value.toISOString().slice(0, 10) } }) }
function resetDate() { router.replace({ query: { ...route.query, date: undefined } }) }
function openDatePicker() { const picker = datePicker.value; if (!picker) return; const showPicker = (picker as HTMLInputElement & { showPicker?: () => void }).showPicker; if (showPicker) showPicker.call(picker); else picker.click() }
function selectDate(event: Event) { const value = (event.target as HTMLInputElement).value; if (value) router.replace({ query: { ...route.query, date: value } }) }
function show(next: 'expense'|'income'|'subscription' = 'expense') { mode.value = next; form.title = ''; form.amount = ''; form.category = ''; form.notes = ''; form.date = date.value; form.currency = (auth.record?.defaultCurrency || 'TWD') as Currency; open.value = true }
async function submit() {
  if (!form.title.trim() || !Number.isFinite(Number(form.amount)) || Number(form.amount) <= 0) return
  saving.value = true
  const amount = Math.round(Number(form.amount) * 100)
  const occurred = (form.date || date.value) + 'T12:00:00.000Z'
  try {
    if (mode.value === 'income') await workspace.addIncome({ title: form.title.trim(), amountMinor: amount, currency: form.currency, category: form.category, receivedOn: occurred, notes: form.notes })
    else if (mode.value === 'subscription') await workspace.addPersonalSubscription({ name: form.title.trim(), amountMinor: amount, currency: form.currency, category: form.category, status: 'active', billingCycle: form.billingCycle as any, billingInterval: 1, startsOn: occurred, nextBilling: occurred, notes: form.notes, paidBy: auth.record?.id || '' })
    else await workspace.addPersonalExpense({ title: form.title.trim(), amountMinor: amount, currency: form.currency, category: form.category, paidBy: auth.record?.id || '', incurredOn: occurred, notes: form.notes })
    if (!workspace.error) open.value = false
  } finally { saving.value = false }
}
async function deleteIncome(id?: string) { if (id && window.confirm(tr('deleteIncomeConfirm', { name: tr('income') }))) await workspace.deleteIncome(id) }
async function loadLedger(value: string) { try { loadError.value = ''; await workspace.refreshPersonalLedger(value) } catch (reason) { loadError.value = reason instanceof Error ? reason.message : tr('requestFailed') } }
watch(() => route.query.date, value => { void loadLedger(String(value || '')) })
onMounted(() => { void loadLedger(String(route.query.date || '')) })
</script>
<template>
<div class="page personal-ledger-page"><PersonalLedgerNav/>
<header class="ledger-header"><div><p class="eyebrow">{{ tr('personalLedger') }}</p><h1>{{ tr('personalLedger') }}</h1><p class="muted">{{ tr('personalLedgerDesc') }}</p></div><button class="primary ledger-add-desktop" @click="show()">{{ tr('addRecord') }}</button></header>
<section class="ledger-datebar card"><button class="icon-button" :aria-label="tr('previousDay')" @click="move(-1)">&lsaquo;</button><button type="button" class="ledger-date-copy date-trigger" :aria-label="tr('chooseDate')" @click="openDatePicker"><strong>{{ label }}</strong><span>{{ ledger?.timezone || auth.record?.timezone || tr('accountTimezone') }} &middot; {{ date }}</span></button><input ref="datePicker" class="ledger-date-picker" type="date" :value="date" :aria-label="tr('chooseDate')" @change="selectDate"><button class="icon-button" :aria-label="tr('nextDay')" @click="move(1)">&rsaquo;</button><button v-if="date!==today()" class="ghost today-button" @click="resetDate">{{ tr('backToToday') }}</button></section>
<p v-if="workspace.error||loadError" class="inline-error">{{ loadError || workspace.error }}</p>
<section v-if="ledger" class="ledger-summary-grid"><article v-for="summary in ledger.summaries" :key="summary.currency" class="ledger-summary card"><div class="summary-top"><span>{{ summary.currency }}</span><span>{{ tr('ledgerRecords', { count: summary.count }) }}</span></div><strong>{{ money(summary.netMinor,summary.currency) }}</strong><div class="summary-lines"><span class="income">{{ tr('income') }} {{ money(summary.incomeMinor,summary.currency) }}</span><span class="expense">{{ tr('expense') }} {{ money(summary.expenseMinor,summary.currency) }}</span><span class="subscription">{{ tr('subscriptions') }} {{ money(summary.subscriptionMinor,summary.currency) }}</span></div></article><article v-if="!ledger.summaries.length" class="ledger-summary card empty-summary"><strong>{{ tr('noRecords') }}</strong><span>{{ tr('noRecordsDesc') }}</span></article></section>
<section class="ledger-list card"><div class="section-heading"><div><p class="eyebrow">{{ tr('timeline') }}</p><h2>{{ tr('ledgerRecords', { count: items.length }) }}</h2></div><span>{{ tr('ledgerRecords', { count: items.length }) }}</span></div><div v-if="!items.length" class="ledger-empty"><div class="empty-icon">*</div><strong>{{ tr('noRecords') }}</strong><p>{{ tr('noRecordsDesc') }}</p></div><article v-for="item in items" :key="item.id" class="ledger-item" :class="'kind-'+item.kind+' status-'+item.status"><div class="item-icon">{{ item.kind==='income' ? '+' : item.kind==='subscription' ? '~' : '-' }}</div><div class="item-main"><strong>{{ item.title }}</strong><span>{{ item.category || tr('uncategorized') }} &middot; {{ sourceLabel(item) }} &middot; {{ statusLabel(item.status) }}</span><small v-if="item.notes">{{ item.notes }}</small></div><div class="item-side"><strong :class="item.kind==='income'?'income':'expense'">{{ item.kind==='income'?'+':'-' }}{{ money(item.amountMinor,item.currency) }}</strong><time>{{ new Date(item.occurredAt).toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'}) }}</time><button v-if="item.kind==='income'&&item.recordId" class="text-button" @click="deleteIncome(item.recordId)">{{ tr('deleteIncome') }}</button></div></article></section>
<button class="ledger-fab" @click="show()" :aria-label="tr('addRecord')">+</button>
<div v-if="open" class="drawer-backdrop" @click.self="open=false"><section class="ledger-drawer" role="dialog" aria-modal="true"><div class="drawer-handle"></div><div class="drawer-title"><div><p class="eyebrow">{{ tr('quickAdd') }}</p><h2>{{ tr('addRecord') }}</h2></div><button class="icon-button" @click="open=false" :aria-label="tr('close')">x</button></div><div class="mode-tabs"><button :class="{active:mode==='expense'}" @click="mode='expense'">{{ tr('expense') }}</button><button :class="{active:mode==='income'}" @click="mode='income'">{{ tr('income') }}</button><button :class="{active:mode==='subscription'}" @click="mode='subscription'">{{ tr('subscriptions') }}</button></div><form class="ledger-form" @submit.prevent="submit"><label>{{ tr('name') }}<input v-model="form.title" required :placeholder="tr('itemPlaceholder')"></label><div class="form-row"><label>{{ tr('amount') }}<input v-model="form.amount" type="number" min="0" step="0.01" required></label><label>{{ tr('currency') }}<select v-model="form.currency"><option>TWD</option><option>USD</option><option>JPY</option><option>EUR</option></select></label></div><label>{{ tr('category') }}<input v-model="form.category" :placeholder="tr('uncategorized')"></label><label v-if="mode==='subscription'">{{ tr('cycle') }}<select v-model="form.billingCycle"><option value="monthly">{{ tr('monthly') }}</option><option value="yearly">{{ tr('yearly') }}</option><option value="weekly">{{ tr('weekly') }}</option></select></label><label>{{ tr('date') }}<input v-model="form.date" type="date" required></label><label>{{ tr('notes') }}<textarea v-model="form.notes" rows="2"></textarea></label><button class="primary full-width" :disabled="saving">{{ saving ? tr('processing') : tr('saveRecord') }}</button></form></section></div>
</div>
</template>
<style scoped>
.personal-ledger-page{max-width:1120px;margin:auto;padding-bottom:2rem}.ledger-header{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin:2rem 0 1.5rem}.ledger-header h1{margin:.25rem 0;font-size:clamp(2rem,5vw,3.4rem)}.ledger-datebar{display:flex;align-items:center;gap:1rem;padding:1rem 1.25rem;margin-bottom:1rem}.ledger-date-copy{display:flex;flex:1;flex-direction:column;text-align:center}.date-trigger{border:0;background:transparent;color:inherit;cursor:pointer;font:inherit}.date-trigger:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:8px}.ledger-date-picker{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.ledger-date-copy strong{font-size:1.2rem}.ledger-date-copy span,.summary-top,.item-main span,.item-main small,.item-side time{color:var(--muted);font-size:.82rem}.icon-button{border:0;background:transparent;color:inherit;font-size:1.8rem;padding:.25rem .6rem;cursor:pointer}.today-button{white-space:nowrap}.ledger-summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-bottom:1rem}.ledger-summary{padding:1.2rem}.summary-top{display:flex;justify-content:space-between}.ledger-summary>strong{display:block;font-size:1.65rem;margin:.65rem 0}.summary-lines{display:grid;gap:.25rem;font-size:.8rem}.income{color:#72d6ad}.expense{color:#ff9b9b}.subscription{color:#aaa4ff}.ledger-list{padding:1.25rem}.section-heading,.drawer-title{display:flex;justify-content:space-between;align-items:center}.section-heading h2,.drawer-title h2{margin:.2rem 0 1rem}.section-heading>span{color:var(--muted)}.ledger-item{display:flex;align-items:center;gap:.8rem;padding:1rem 0;border-top:1px solid var(--border)}.item-icon{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:50%;background:var(--surface-strong);font-size:1.3rem}.item-main{display:grid;gap:.2rem;flex:1;min-width:0}.item-main strong{overflow:hidden;text-overflow:ellipsis}.item-main small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-side{text-align:right;display:grid;gap:.2rem;justify-items:end}.item-side strong{white-space:nowrap}.text-button{background:none;border:0;color:var(--muted);cursor:pointer;font-size:.75rem}.ledger-empty,.empty-summary{text-align:center;padding:2.5rem;color:var(--muted)}.empty-summary{display:flex;flex-direction:column;gap:.4rem}.empty-summary strong,.ledger-empty strong{color:var(--text)}.empty-icon{font-size:2rem}.ledger-fab{display:none}.drawer-backdrop{position:fixed;inset:0;background:#05071199;z-index:50;display:flex;align-items:flex-end;justify-content:center}.ledger-drawer{width:min(560px,100%);max-height:90dvh;overflow:auto;background:var(--surface);border:1px solid var(--border);border-radius:24px 24px 0 0;padding:1rem 1.25rem calc(1.25rem + env(safe-area-inset-bottom));box-shadow:0 -20px 60px #0008}.drawer-handle{width:44px;height:4px;background:var(--muted);opacity:.5;border-radius:99px;margin:0 auto 1rem}.mode-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:.4rem;background:var(--surface-strong);padding:.3rem;border-radius:12px;margin-bottom:1.1rem}.mode-tabs button{border:0;background:none;color:var(--muted);padding:.65rem;border-radius:9px;cursor:pointer}.mode-tabs button.active{background:var(--accent);color:white}.ledger-form{display:grid;gap:.8rem}.ledger-form label{display:grid;gap:.35rem;color:var(--muted);font-size:.85rem}.ledger-form input,.ledger-form select,.ledger-form textarea{width:100%;box-sizing:border-box;border:1px solid var(--border);border-radius:10px;background:var(--surface-strong);color:var(--text);padding:.75rem;font:inherit}.form-row{display:grid;grid-template-columns:1fr .7fr;gap:.7rem}.full-width{width:100%}.inline-error{color:#ff9b9b;margin:.7rem 0}
@media(max-width:900px){.personal-ledger-page{padding:1rem 1rem calc(7rem + env(safe-area-inset-bottom))}.ledger-header{margin:1rem 0;align-items:flex-start}.ledger-add-desktop{display:none}.ledger-fab{display:block;position:fixed;right:1.1rem;bottom:calc(88px + env(safe-area-inset-bottom));z-index:30;width:3.5rem;height:3.5rem;border:0;border-radius:50%;background:var(--accent);color:white;font-size:1.7rem;box-shadow:0 10px 30px #0008}.ledger-datebar{padding:.8rem}.today-button{font-size:.75rem;padding:.45rem}.ledger-summary-grid{grid-template-columns:1fr 1fr;gap:.65rem}.ledger-summary{padding:.85rem}.ledger-summary>strong{font-size:1.15rem}.summary-lines{font-size:.7rem}.section-heading h2{font-size:1.25rem}}
@media(max-width:420px){.ledger-summary-grid{grid-template-columns:1fr}.form-row{grid-template-columns:1fr 1fr}}
</style>